112	        this.birthDate = birthDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    /** Stable identifier shared by owners of the same household (matching last name and postcode). */
120	    @Transient
121	    public String getHouseholdId() {
122	        return HouseholdId.of(getLastName(), this.postcode);
123	    }
124	
125	    public void setCustomerCode(String customerCode) {
126	        this.customerCode = customerCode;
127	    }
128	
129	    /** Derived duplicate-detection key: normalized telephone, email (or empty) and household id
130	     *  joined with {@code '|'}. Two owners are duplicates only when their whole key matches, so a
131	     *  shared telephone alone (with matching email) is a collision regardless of household. */
132	    @Transient
133	    public String getIdentityKey() {
134	        return (this.telephone == null ? "" : this.telephone) + "|"
135	            + (this.email == null ? "" : this.email) + "|";
136	    }
137	
138	    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
139	    @Transient
140	    public String getMembershipNumber() {
141	        return MembershipNumber.of(this.customerCode, this.registrationDate);
142	    }
143	
144	    /** Luhn check digit over the digits of the {@code customerCode}. */
145	    @Transient
146	    public Integer getCheckDigit() {
147	        return CheckDigit.of(this.customerCode);
148	    }
149	
150	    public Integer getNamesakeCount() {
151	        return this.namesakeCount;
152	    }
153	
154	    public void setNamesakeCount(Integer namesakeCount) {
155	        this.namesakeCount = namesakeCount;
156	    }
157	
158	    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
159	     *  captured when the owner was created, including this owner. */
160	    public Integer getHouseholdMemberCount() {
161	        return this.householdMemberCount;
162	    }
163	
164	    public void setHouseholdMemberCount(Integer householdMemberCount) {
165	        this.householdMemberCount = householdMemberCount;
166	    }
167	
168	    /** True when this owner, at creation, shared an existing owner's last name and postcode
169	     *  but had a different telephone (a soft, non-hard duplicate). */
170	    public Boolean getPossibleDuplicate() {
171	        return this.possibleDuplicate;
172	    }
173	
174	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
175	        this.possibleDuplicate = possibleDuplicate;
176	    }
177	
178	    /** Id of the existing owner this owner possibly duplicates, when {@link #getPossibleDuplicate()}. */
179	    public Integer getPossibleDuplicateOf() {
180	        return this.possibleDuplicateOf;
181	    }
182	
183	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
184	        this.possibleDuplicateOf = possibleDuplicateOf;
185	    }
186	
187	    public String getEmail() {
188	        return this.email;
189	    }
190	
191	    public void setEmail(String email) {
192	        this.email = email == null ? null : email.toLowerCase();
193	    }
194	
195	    public String getAddress() {
196	        return this.address;
197	    }
198	
199	    public void setAddress(String address) {
200	        this.flatAddress = AddressNormalizer.normalize(address);
201	        this.address = composeAddress();
202	    }
203	
204	    public String getAddressLine1() {
205	        return this.addressLine1;
206	    }
207	
208	    public void setAddressLine1(String addressLine1) {
209	        this.addressLine1 = AddressNormalizer.normalize(addressLine1);
210	        this.address = composeAddress();
211	    }
212	
213	    public String getAddressLine2() {
214	        return this.addressLine2;
215	    }
216	
217	    public void setAddressLine2(String addressLine2) {
218	        this.addressLine2 = AddressNormalizer.normalize(addressLine2);
219	        this.address = composeAddress();
220	    }
221	
222	    /** Prefer the structured lines when {@code addressLine1} is present (line 2 appended after a
223	     *  single space), otherwise fall back to the flat address, so all address readers stay consistent. */
224	    private String composeAddress() {
225	        if (this.addressLine1 == null || this.addressLine1.isBlank()) {
226	            return this.flatAddress;
227	        }
228	        return this.addressLine2 == null ? this.addressLine1 : this.addressLine1 + " " + this.addressLine2;
229	    }
230	
231	    public String getPostcode() {
232	        return this.postcode;
233	    }
234	
235	    public void setPostcode(String postcode) {
236	        this.postcode = postcode;
237	    }
238	
239	    public String getCity() {
240	        return this.city;
241	    }
242	
243	    public void setCity(String city) {
244	        this.city = city;
245	    }
246	
247	    public String getTelephone() {
248	        return this.telephone;
249	    }
250	
251	    public void setTelephone(String telephone) {
252	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
253	    }
254	
255	    protected Set<Pet> getPetsInternal() {
256	        if (this.pets == null) {
257	            this.pets = new HashSet<>();
258	        }
259	        return this.pets;
260	    }
261	
262	    protected void setPetsInternal(Set<Pet> pets) {
263	        this.pets = pets;
264	    }
265	
266	    public List<Pet> getPets() {
267	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
268	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
269	        return Collections.unmodifiableList(sortedPets);
270	    }
271	
272	    public void setPets(List<Pet> pets) {
273	        this.pets = new HashSet<>(pets);
274	    }
275	
276	    public void addPet(Pet pet) {
277	        getPetsInternal().add(pet);
278	        pet.setOwner(this);
279	    }
280	
281	    /**
282	     * Return the Pet with the given name, or null if none found for this Owner.
283	     *
284	     * @param name to test
285	     * @return true if pet name is already in use
286	     */
287	    public Pet getPet(String name) {
288	        return getPet(name, false);
289	    }
290	
291	    /**
292	     * Return the Pet with the given name, or null if none found for this Owner.
293	     *
294	     * @param name to test
295	     * @return true if pet name is already in use
296	     */
297	    public Pet getPet(String name, boolean ignoreNew) {
298	        name = name.toLowerCase();
299	        for (Pet pet : getPetsInternal()) {
300	            if (!ignoreNew || !pet.isNew()) {
301	                String compName = pet.getName();
302	                compName = compName.toLowerCase();
303	                if (compName.equals(name)) {
304	                    return pet;
305	                }
306	            }
307	        }
308	        return null;
309	    }
310	
311	    public Pet getPet(Integer petId) {
312	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
313	    }
314	
315	    @Override
316	    public String toString() {
317	        return new ToStringCreator(this)
318	
319	            .append("id", this.getId())
320	            .append("new", this.isNew())
321	            .append("lastName", this.getLastName())
322	            .append("firstName", this.getFirstName())
323	            .append("address", this.address)
324	            .append("city", this.city)
325	            .append("telephone", this.telephone)
326	            .toString();
327	    }
328	}
